import bisect

def solve(nums):
    # If empty list, LIS length is 0
    if not nums:
        return 0
    # tails[i] will be the minimum possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # Find the insertion point for x in tails to replace or extend
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

