    # Initialize DP array where dp[i] = min coins to make amount i
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        min_count = float('inf')
        for c in coins:
            if c <= a:
                prev = dp[a - c]
                if prev + 1 < min_count:
                    min_count = prev + 1
        dp[a] = min_count
    return dp[amount] if dp[amount] != float('inf') else -1

