def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Handles non‑iterable inputs by returning 0. Uses the classic patience
    sorting method with O(n log n) time and O(n) space.
    """
    # Guard against None or non‑iterable inputs
    try:
        iterator = iter(nums)
    except TypeError:
        return 0
    # Convert to list to allow multiple passes if needed (not required here)
    # but we avoid copying large data if it's already a list
    if not isinstance(nums, list):
        nums = list(nums)
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc. subseq of length i+1
    for x in nums:
        # Find position to replace: first element >= x (strictly increasing)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

def solve(tokens):
    """Evaluate a Reverse Polish Notation expression.
    tokens: list of strings, each is an integer literal or one of '+', '-', '*', '/'.
    Returns the integer result. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division, truncate toward zero
                # Using int() on true division gives truncation toward zero.
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

