    # try all subsets
    best = 0
    n = len(meetings)
    from itertools import combinations
    for r in range(n+1):
        for combo in combinations(meetings, r):
            # check if non-overlapping
            ok = True
            # normalize each
            intervals = []
            for m in combo:
                s, e = m[0], m[1]
                if s > e:
                    s, e = e, s
                intervals.append((s, e))
            intervals.sort()
            for i in range(1, len(intervals)):
                if intervals[i][0] < intervals[i-1][1]:
                    ok = False
                    break
            if ok:
                best = max(best, len(intervals))
    return best

